checkout_error_rate::baseline::v2.text:
{
  "claims": [
    {
      "id": "CL-01",
      "statement": "A pre-registered, session-randomised experiment on web card checkout (412,905 enrolled sessions, clean sample-ratio check) found inline authorisation recovery raised payment-authorisation step completion by 3.4 percentage points.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Absolute difference +3.4 percentage points, 95% confidence interval [+3.2, +3.6], p < 0.001.", "locator": "Primary result"},
        {"evidence_id": "EV-f71c3028", "quote": "Enrolled sessions: 412,905. Control 206,338, treatment 206,567.", "locator": "Design"},
        {"evidence_id": "EV-f71c3028", "quote": "Sample-ratio mismatch check: p = 0.72. No imbalance detected.", "locator": "Design"}
      ],
      "support_level": "strong",
      "rationale": "Large randomised comparison, concurrent arms, primary metric registered before launch. Strong for the step metric on web card sessions only."
    },
    {
      "id": "CL-02",
      "statement": "An independent gateway-log series replicates the effect outside the experiment window: North region moved from 91.3–91.5% before rollout to 93.1% at 50% ramp and 94.7–95.0% at 100%, while the rest of the network stayed at 91.1–91.4% with rollout not started.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-1ce4264b", "quote": "payment_auth_completion_percent: 91.5", "locator": "north, week 2026-06-22, rollout_state: not_started"},
        {"evidence_id": "EV-04a161ba", "quote": "synthetic - inline authorisation recovery enabled for half of north-region web card sessions from this week; series compiled from payment gateway logs and not from experiment instrumentation", "locator": "north, week 2026-06-29, 93.1%"},
        {"evidence_id": "EV-43ccac17", "quote": "payment_auth_completion_percent: 95.0", "locator": "north, week 2026-07-27, ramped_100_percent"},
        {"evidence_id": "EV-fe4bda91", "quote": "payment_auth_completion_percent: 91.2", "locator": "rest_of_network, week 2026-07-27, not_started"},
        {"evidence_id": "EV-33b7280a", "quote": "The payments platform team now publishes a weekly payment authorisation completion series compiled directly from gateway logs. It is produced independently of experiment instrumentation.", "locator": "CHG-2026-09"}
      ],
      "support_level": "strong",
      "rationale": "Non-randomised staged rollout, but the comparison group is concurrent, the data source is independent of experiment instrumentation, and the period is outside the May campaign."
    },
    {
      "id": "CL-03",
      "statement": "The experiment did not measure the outcome this decision targets: the effect on completed orders and on end-to-end checkout failure rate was recorded but never analysed.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Order completion per enrolled session was recorded but was not a registered metric and has not been analysed.", "locator": "What this experiment does not report"},
        {"evidence_id": "EV-f71c3028", "quote": "The effect of the treatment on completed orders, on basket value, or on the end-to-end checkout failure rate is not a result of this experiment.", "locator": "What this experiment does not report"}
      ],
      "support_level": "strong",
      "rationale": "Stated explicitly by the experiment owner. This is an unmeasured result, not a null result."
    },
    {
      "id": "CL-04",
      "statement": "The fraud guardrail reading is flat but partial: chargebacks were counted only to 30 days when scheme rules allow disputes to 120 days.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Chargeback rate on orders originating in enrolled sessions: control 0.11%, treatment 0.11%. Difference +0.00 points, 95% confidence interval [-0.02, +0.02].", "locator": "Guardrails"},
        {"evidence_id": "EV-f71c3028", "quote": "Chargebacks were counted to 30 days after order. Scheme rules permit a dispute up to 120 days after the transaction, so the chargeback reading is partial and the series is still being collected.", "locator": "Guardrails"}
      ],
      "support_level": "moderate",
      "rationale": "Measured and precise for the 30-day window; the tail is unobserved, so 'no fraud increase' is not yet established."
    },
    {
      "id": "CL-05",
      "statement": "The reported deterioration from 4.1% to 6.4% spans a definition change: from 2026-01-01 the failure numerator also counts client-side payment-frame timeouts, and no period before 2026-Q1 was restated.",
      "claim_type": "assumption",
      "citations": [
        {"evidence_id": "EV-37d90681", "quote": "The numerator now also counts checkout sessions terminated by a client-side timeout, meaning the payment frame did not reach an interactive state within 20 seconds. These sessions raise no server-side error and were previously excluded from the numerator.", "locator": "CHG-2026-02 detail"},
        {"evidence_id": "EV-37d90681", "quote": "None. Periods before 2026-Q1 remain published under v2.", "locator": "CHG-2026-02 backfill"},
        {"evidence_id": "EV-3c51f8a3", "quote": "value: 4.1", "locator": "2025-Q4, note: synthetic - defn v2"},
        {"evidence_id": "EV-b7bafb67", "quote": "value: 6.4", "locator": "2026-Q2, note: synthetic - defn v3"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-8cc44847", "quote": "Checkout failure rate has risen from 4.1% in 2025-Q4 to 6.4% in 2026-Q2, a deterioration of more than half in two quarters.", "locator": "Current position"}
      ],
      "support_level": "moderate",
      "rationale": "Labelled an assumption because the size of the definitional contribution has not been quantified; nobody has produced a v2-to-v3 bridge. The comparison as published is not like-for-like."
    },
    {
      "id": "CL-06",
      "statement": "Any change to the card authorisation flow needs payment-scheme compliance sign-off, currently ten working days, before release.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-e86d8670", "quote": "Any change to the card authorisation flow requires payment-scheme compliance sign-off before release. Sign-off currently takes ten working days from submission of the change record.", "locator": "Changes to the authorisation flow"}
      ],
      "support_level": "strong",
      "rationale": "Stated policy, owner legal-and-payments-compliance, updated 2026-04-30."
    },
    {
      "id": "CL-07",
      "statement": "Re-presenting a payment form is permitted only from a tokenised reference, and the tested treatment re-presents from a tokenised card reference.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-e86d8670", "quote": "A payment form may be re-presented only from a tokenised reference held by the payment service.", "locator": "Card data"},
        {"evidence_id": "EV-f71c3028", "quote": "re-presents the form from the tokenised card reference so that only the failing field has to be corrected", "locator": "What was changed"}
      ],
      "support_level": "moderate",
      "rationale": "The design description matches the policy wording; a formal compliance determination is still the sign-off step's job, not something the evidence records."
    },
    {
      "id": "CL-08",
      "statement": "Experiment datasets containing payment identifiers are deleted 180 days after the experiment closes, and re-analysis is not possible afterwards; the experiment window closed 2026-06-14.",
      "claim_type": "governance_constraint",
      "citations": [
        {"evidence_id": "EV-e86d8670", "quote": "Experiment datasets containing payment identifiers are deleted 180 days after the experiment closes. Re-analysis is not possible from the original records after that date.", "locator": "Experiment data"},
        {"evidence_id": "EV-f71c3028", "quote": "Window: 2026-05-04 to 2026-06-14, six weeks.", "locator": "Design"}
      ],
      "support_level": "strong",
      "rationale": "Policy plus dated window. This puts a hard clock on the missing order-completion analysis."
    },
    {
      "id": "CL-09",
      "statement": "A checkout change freeze runs 2026-09-07 to 2026-10-05; anything not released before 2026-09-07 waits until October.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-5e159e3a", "quote": "A change freeze applies to all checkout services from 2026-09-07 to 2026-10-05 for peak trading. Anything not released before 2026-09-07 waits until October.", "locator": "Release calendar"},
        {"evidence_id": "EV-8cc44847", "quote": "Peak trading runs from mid-September. A change freeze applies across checkout for the duration of the peak window.", "locator": "Priorities and constraints"}
      ],
      "support_level": "strong",
      "rationale": "Two independent documents state the freeze; engineering gives exact dates."
    },
    {
      "id": "CL-10",
      "statement": "Payment processing cost per order is the binding financial constraint and any proposal that raises it needs finance approval before rollout.",
      "claim_type": "business_constraint",
      "citations": [
        {"evidence_id": "EV-8cc44847", "quote": "Payment processing cost per order is the binding financial constraint. Any proposal that raises it requires finance approval before rollout.", "locator": "Priorities and constraints"},
        {"evidence_id": "EV-540bba8d", "quote": "value: 100.0", "locator": "2026-Q2 payment_processing_cost_index, surface: all"}
      ],
      "support_level": "strong",
      "rationale": "Explicit constraint. Note the index is published at surface 'all' with no attribution to any intervention."
    },
    {
      "id": "CL-11",
      "statement": "The inline recovery pattern cannot be applied to stored-wallet payments without a change to a wallet integration specification the team does not own, and the app checkout shares no code with the web payment step with no estimate produced.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-5e159e3a", "quote": "The inline recovery pattern cannot be applied to a redirect flow without a change to the wallet integration specification, which is not ours to change.", "locator": "Wallet payments"},
        {"evidence_id": "EV-5e159e3a", "quote": "The app checkout is a separate implementation on the mobile payments SDK and shares no code with the web payment step. No estimate has been produced for the app implementation.", "locator": "Mobile app checkout"}
      ],
      "support_level": "strong",
      "rationale": "Engineering-owned constraints document, updated 2026-07-22."
    },
    {
      "id": "CL-12",
      "statement": "The app surface emits no step-level checkout events, so there is no app funnel, no app payment-step metric, and no experiment can run on the app until instrumentation is added.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-5e159e3a", "quote": "There is no app funnel and no experiment can be run on the app surface until instrumentation is added.", "locator": "Mobile app checkout"},
        {"evidence_id": "EV-5a09f4bc", "quote": "The replacement schema emits order-level events only. Step-level checkout events are no longer emitted by the app.", "locator": "CHG-2026-04, effective 2026-02-10"},
        {"evidence_id": "EV-031e8c0f", "quote": "synthetic - not instrumented; the app checkout emits no step-level events", "locator": "app_payment_step_completion, 2026-Q3-to-date"}
      ],
      "support_level": "strong",
      "rationale": "Three consistent records, including a blank metric row."
    },
    {
      "id": "CL-13",
      "statement": "In the 2026-Q2 web funnel the largest single session loss is slot selection (133,000 sessions), larger than payment authorisation (81,500), but the split between slot unavailability and interface difficulty is not measured.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-3424ee59", "quote": "sessions_lost: 133000", "locator": "2026-Q2 web, slot_selection"},
        {"evidence_id": "EV-3424ee59", "quote": "synthetic - largest single loss in the funnel; the split between slot unavailability and interface difficulty is not measured", "locator": "note"},
        {"evidence_id": "EV-39930965", "quote": "sessions_lost: 81500", "locator": "2026-Q2 web, payment_authorisation"}
      ],
      "support_level": "strong",
      "rationale": "Same dated dataset for both steps. The cause attribution behind the slot loss is explicitly absent."
    },
    {
      "id": "CL-14",
      "statement": "Slot-step losses are largely outside the failure-rate metric and outside checkout's control: the failure numerator excludes error-free abandonment, and checkout cannot create slot capacity.",
      "claim_type": "assumption",
      "citations": [
        {"evidence_id": "EV-37d90681", "quote": "checkout_failure_rate = checkout sessions ending in a system-reported error, divided by all checkout sessions started. Sessions the customer abandons without an error are not counted in the numerator.", "locator": "CHG-2026-02 definition"},
        {"evidence_id": "EV-5e159e3a", "quote": "Slot capacity is generated by the fulfilment planning service. Checkout can display slots and hold them; it cannot create them.", "locator": "Delivery slots"},
        {"evidence_id": "EV-8cc44847", "quote": "Fulfilment slot capacity is owned by the fulfilment planning team and is not part of the checkout reliability programme.", "locator": "Out of scope for FY26"}
      ],
      "support_level": "moderate",
      "rationale": "Definition and ownership are documented; that slot losses are error-free abandonment rather than timeouts is inference, not measured."
    },
    {
      "id": "CL-15",
      "statement": "Payment problems were the largest support contact topic in 2026-Q2 at 34.8% of contacts (9,140), with 'order not placed, unclear why' a further 15.3% and 'slot not available' only 4.5%.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-96fab67f", "quote": "share_of_contacts_percent: 34.8", "locator": "2026-Q2, payment_declined_or_error, contacts: 9140"},
        {"evidence_id": "EV-a5da645d", "quote": "share_of_contacts_percent: 15.3", "locator": "2026-Q2, order_not_placed_unclear_why"},
        {"evidence_id": "EV-ddff174d", "quote": "share_of_contacts_percent: 4.5", "locator": "2026-Q2, slot_not_available"}
      ],
      "support_level": "strong",
      "rationale": "Fact about contact mix across all surfaces. It is not a measure of where sessions are lost: the denominator is contacts, and customers who abandon at slot selection have little reason to contact support."
    },
    {
      "id": "CL-16",
      "statement": "The Director of Growth believes the 3.4-point lift is a May promotion artefact; she had not checked how sessions were assigned to arms.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-5b4968e2", "quote": "The 3.4 point lift is a May promotion artefact. That window had the bank-holiday campaign in it and the traffic mix was nothing like a normal week. I would not bank on it.", "locator": "Director of Growth, Halle Brennig"},
        {"evidence_id": "EV-5b4968e2", "quote": "Asked how sessions were assigned to the two arms, she said she had not looked.", "locator": "Director of Growth, Halle Brennig"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Because both arms ran concurrently under session-level randomisation, promotional traffic was allocated to the arms in the same proportion, and no calendar effect can produce a difference between them.", "locator": "Primary result"}
      ],
      "support_level": "low",
      "rationale": "A concurrent randomised design cannot produce a between-arm calendar artefact, and the June–July North gateway series lies outside the campaign window."
    },
    {
      "id": "CL-17",
      "statement": "The Head of Payments Risk believes every retry mechanism shipped has increased chargebacks and wants six more months of data; the underlying comparison was never written down.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-5b4968e2", "quote": "Every retry mechanism we have shipped has increased chargebacks. I would want a further six months of data before we call this safe.", "locator": "Head of Payments Risk, Ines Kovaleva"},
        {"evidence_id": "EV-5b4968e2", "quote": "Asked which mechanisms and by how much, she said the comparison had never been written down.", "locator": "Head of Payments Risk, Ines Kovaleva"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Chargeback rate on orders originating in enrolled sessions: control 0.11%, treatment 0.11%. Difference +0.00 points, 95% confidence interval [-0.02, +0.02].", "locator": "Guardrails"}
      ],
      "support_level": "low",
      "rationale": "Unrecorded prior experience. It should not be dismissed, though: the measured guardrail only covers 30 days of a 120-day dispute window, so her concern maps onto a genuine measurement gap."
    },
    {
      "id": "CL-18",
      "statement": "The VP Digital wants the change shipped to web, app and wallet before the September peak.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-5b4968e2", "quote": "It works. Ship it to every surface - web, app and wallet - before the September peak.", "locator": "VP Digital, Tomasz Reddick"}
      ],
      "opposing_citations": [
        {"evidence_id": "EV-f71c3028", "quote": "The treatment was never shown to an app session or to a stored-wallet payment. Nothing here describes those flows.", "locator": "What this experiment does not report"}
      ],
      "support_level": "low",
      "rationale": "Executive preference. Seniority does not extend the evidence to surfaces the treatment was never shown on, and the wallet path is technically blocked."
    },
    {
      "id": "CL-19",
      "statement": "A vendor deck claims a hosted checkout reduces payment failures by 40%, with no baseline, sample size, method or market stated.",
      "claim_type": "stakeholder_opinion",
      "citations": [
        {"evidence_id": "EV-5b4968e2", "quote": "A vendor deck circulated before the meeting claims their hosted checkout reduces payment failures by 40%.", "locator": "Vendor briefing"},
        {"evidence_id": "EV-5b4968e2", "quote": "The deck does not state a baseline, a sample size, a comparison method, or the market the figure came from. No independent evaluation was provided.", "locator": "Vendor briefing"}
      ],
      "support_level": "low",
      "rationale": "An unqualified number is an opinion about a number."
    },
    {
      "id": "CL-20",
      "statement": "The February 2026 slot picker redesign could not measure its own effect: it shipped to all web customers with no holdout and was confounded by two depots coming online two weeks later.",
      "claim_type": "fact",
      "citations": [
        {"evidence_id": "EV-f71c3028", "quote": "Slot-step completion was 89.1% in the four weeks before release and 89.4% in the four weeks after.", "locator": "Prior work: slot picker refresh, February 2026"},
        {"evidence_id": "EV-f71c3028", "quote": "The interface change and the capacity increase cannot be separated, and the release had no design capable of measuring its own effect.", "locator": "Prior work"}
      ],
      "support_level": "strong",
      "rationale": "This is an unmeasured result, not evidence that slot-interface work has a small effect."
    },
    {
      "id": "CL-21",
      "statement": "The authorisation flow is no longer frozen: the payments platform migration completed 2026-03-20 and changes to the flow can ship again.",
      "claim_type": "technical_constraint",
      "citations": [
        {"evidence_id": "EV-5e159e3a", "quote": "The payments platform migration completed on 2026-03-20. The authorisation flow was frozen for the duration of that migration. It is no longer frozen and changes to it can ship again.", "locator": "Payments platform"}
      ],
      "support_level": "strong",
      "rationale": "Removes the main platform blocker to a network rollout before the peak freeze."
    }
  ],
  "contradictions": [
    {
      "id": "CT-01",
      "topic": "Whether checkout failure rate genuinely deteriorated by more than half, or partly changed definition",
      "kind": "temporal_conflict",
      "side_a": {"evidence_id": "EV-8cc44847", "quote": "Checkout failure rate has risen from 4.1% in 2025-Q4 to 6.4% in 2026-Q2, a deterioration of more than half in two quarters.", "locator": "business_objectives.md, Current position"},
      "side_b": {"evidence_id": "EV-37d90681", "quote": "None. Periods before 2026-Q1 remain published under v2.", "locator": "CHG-2026-02 backfill"},
      "summary": "The 4.1% figure belongs to 2025-Q4 and is published under definition v2; 6.4% belongs to 2026-Q2 under v3, which added client-side payment-frame timeouts to the numerator with no backfill. The strategy prose compares across the break. The 2026-Q1 6.8% figure quoted by the Finance Business Partner ('Something broke in January') sits on the first v3 period, i.e. exactly the period the definition changed.",
      "how_to_resolve": "Ask analytics-engineering to restate 2025-Q3 and 2025-Q4 under v3, or publish 2026-Q1/Q2 on a v2-equivalent basis, and to report the timeout-only component separately. That determines how much of the gap is a real regression and against which definition the 4.0% FY26 target is judged."
    },
    {
      "id": "CT-02",
      "topic": "Is the +3.4pp lift a May campaign artefact?",
      "kind": "claim_conflict",
      "side_a": {"evidence_id": "EV-5b4968e2", "quote": "The 3.4 point lift is a May promotion artefact. That window had the bank-holiday campaign in it and the traffic mix was nothing like a normal week. I would not bank on it.", "locator": "Director of Growth"},
      "side_b": {"evidence_id": "EV-f71c3028", "quote": "Because both arms ran concurrently under session-level randomisation, promotional traffic was allocated to the arms in the same proportion, and no calendar effect can produce a difference between them.", "locator": "Experiment report, Primary result"},
      "summary": "A concurrent randomised design allocates promotional traffic to both arms, so a calendar effect cannot generate a between-arm difference. Separately, the North gateway-log series shows the same size of movement in late June and July, outside the campaign window and independent of experiment instrumentation.",
      "how_to_resolve": "Walk the Director of Growth through the assignment mechanism and the North gateway series (91.3–91.5% not started, 94.7–95.0% at full ramp) and ask her to state what additional cut she would accept as disconfirming, e.g. the result restricted to non-promotional weeks."
    },
    {
      "id": "CT-03",
      "topic": "Does inline recovery raise chargebacks?",
      "kind": "claim_conflict",
      "side_a": {"evidence_id": "EV-5b4968e2", "quote": "Every retry mechanism we have shipped has increased chargebacks. I would want a further six months of data before we call this safe.", "locator": "Head of Payments Risk"},
      "side_b": {"evidence_id": "EV-f71c3028", "quote": "Chargeback rate on orders originating in enrolled sessions: control 0.11%, treatment 0.11%. Difference +0.00 points, 95% confidence interval [-0.02, +0.02].", "locator": "Experiment report, Guardrails"},
      "summary": "The measurement shows no difference; the risk owner's prior experience says otherwise but was never documented. The measurement is also incomplete — 30 days of a 120-day dispute window.",
      "how_to_resolve": "Extend the chargeback series on enrolled sessions to 90 and 120 days and publish it before the 180-day experiment-data deletion date; ask payments risk to name the prior mechanisms so a written comparison can be attempted."
    },
    {
      "id": "CT-04",
      "topic": "Where checkout failures actually concentrate",
      "kind": "scope_conflict",
      "side_a": {"evidence_id": "EV-3424ee59", "quote": "synthetic - largest single loss in the funnel; the split between slot unavailability and interface difficulty is not measured", "locator": "2026-Q2 web funnel, slot_selection, 133,000 lost"},
      "side_b": {"evidence_id": "EV-96fab67f", "quote": "share_of_contacts_percent: 34.8", "locator": "2026-Q2 support contacts, payment_declined_or_error"},
      "summary": "Both are true of different segments and different denominators. Measured in sessions on the web funnel, slot selection is the largest single loss (133,000 vs 81,500 at payment authorisation). Measured in support contacts across all surfaces, payment problems are the largest topic at 34.8%. The Support Manager's inference that contacts show 'where the failures are' does not follow, because abandonment at slot selection rarely generates a contact and is excluded from the failure-rate numerator.",
      "how_to_resolve": "Instrument slot-step exit reasons (no acceptable slot offered vs interface abandonment) and publish sessions-lost alongside contacts, so both metrics are stated per session with the same denominator and surface."
    },
    {
      "id": "CT-05",
      "topic": "Can the fix be shipped to every surface before peak?",
      "kind": "scope_conflict",
      "side_a": {"evidence_id": "EV-5b4968e2", "quote": "It works. Ship it to every surface - web, app and wallet - before the September peak.", "locator": "VP Digital"},
      "side_b": {"evidence_id": "EV-5e159e3a", "quote": "The inline recovery pattern cannot be applied to a redirect flow without a change to the wallet integration specification, which is not ours to change.", "locator": "technical_constraints.md, Wallet payments"},
      "summary": "The executive ask covers three surfaces; the evidence covers one. Wallet requires a third-party specification change, and the app is a separate implementation with no estimate and no step-level instrumentation to detect harm.",
      "how_to_resolve": "Ask engineering for a written scoping note on app implementation plus instrumentation, and confirm with the wallet provider whether any in-flow recovery is permitted under the current integration spec. Until then, the deliverable that can be committed before 2026-09-07 is web card sessions."
    },
    {
      "id": "CT-06",
      "topic": "Which figure is the pre-rollout payment authorisation baseline",
      "kind": "metric_conflict",
      "side_a": {"evidence_id": "EV-3bb6fc48", "quote": "synthetic - includes six weeks of EXP-2026-04 treatment exposure", "locator": "2026-Q2 payment_auth_completion_rate = 91.9%"},
      "side_b": {"evidence_id": "EV-7e7c87c0", "quote": "payment_auth_completion_percent: 91.2", "locator": "rest_of_network, week 2026-06-15, rollout_state: not_started"},
      "summary": "The quarterly 91.9% is a blend that already contains six weeks of treatment exposure, so it cannot be used as the counterfactual. The untreated baseline is the ~91.2% gateway-log level in region groups where rollout has not started.",
      "how_to_resolve": "Have analytics publish payment_auth_completion_rate split by rollout state, and use the gateway series rather than the quarterly blend for any before/after claim."
    }
  ],
  "missing_evidence": [
    {
      "id": "GAP-01",
      "question": "What is the checkout failure rate, session volume and payment-step completion on the mobile app?",
      "impact": "would_change_recommendation",
      "why_it_matters": "Every failure-rate, completion and funnel metric in the evidence is labelled surface: web, and the app has no step-level events at all. If the app carries a large share of sessions or a much worse failure rate, the highest-value intervention could be app instrumentation rather than a web rollout. Blank is not zero: the app metric row exists and was never populated.",
      "how_to_obtain": "Derive app order-level conversion from the replacement schema as an interim proxy, and commission a scoping estimate for step-level app instrumentation from engineering.",
      "was_searched": true
    },
    {
      "id": "GAP-02",
      "question": "Did the inline recovery treatment increase completed orders per enrolled session, and by how much?",
      "impact": "would_change_support_level",
      "why_it_matters": "This is the outcome the decision is about. The data was recorded but never analysed, and the payment-identifier dataset is deleted 180 days after the 2026-06-14 close, after which re-analysis is impossible. A step-level gain that does not convert to orders would not move the FY26 goals.",
